function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw kimchi bowl
  ctx.beginPath();
  ctx.arc(W/2, H/2, 100, 0, 2 * Math.PI);
  ctx.stroke();

  // draw cabbage
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + Math.cos(t + i) * 50, H/2 + Math.sin(t + i) * 50, 20, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.fillStyle = 'green';
    ctx.fill();
  }

  // draw fermentation layers
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.rect(W/2 - 80 + i * 20, H/2 - 20, 10, 40);
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.strokeStyle = 'black';
    ctx.stroke();
  }

  // draw stick figure chef
  ctx.beginPath();
  ctx.arc(W/2 - 150, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 - 30);
  ctx.lineTo(W/2 - 150, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 - 10);
  ctx.lineTo(W/2 - 170, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 150, H/2 - 10);
  ctx.lineTo(W/2 - 130, H/2 + 10);
  ctx.stroke();

  ctx.restore();
}
